"use client";

import { AnimatedTooltip } from "@/components/application/animations/expanded/controls/animated-tooltip";

export default function Example() {
  return (
    <AnimatedTooltip
      content={"Browse running shoes collection"}
      duration={0.25}
      followPointer={false}
      delay={0.2}
      hideDelay={0.06}
      offset={12}
      placement={"top"}
    >
      <button type="button">Running</button>
    </AnimatedTooltip>
  );
}

