"use client";
import {
  cloneElement,
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type ReactElement,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion } from "motion/react";
import {
  ControlStyles,
  controlVariables,
  useControlTransition,
  useControlValue,
  type ControlAppearance,
} from "./control-shared";
export interface AnimatedTooltipProps extends ControlAppearance {
  children: ReactElement<{ "aria-describedby"?: string }>;
  content: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  placement?: "top" | "bottom" | "left" | "right";
  followPointer?: boolean;
  delay?: number;
  hideDelay?: number;
  offset?: number;
  disabled?: boolean;
}
export function AnimatedTooltip({
  children,
  content,
  open,
  defaultOpen = false,
  onOpenChange,
  placement = "top",
  followPointer = false,
  delay = 0.2,
  hideDelay = 0.06,
  offset = 12,
  disabled = false,
  ...appearance
}: AnimatedTooltipProps) {
  const [isOpen, setOpen] = useControlValue(open, defaultOpen, onOpenChange);
  const [mounted, setMounted] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0, ready: false, side: placement });
  const trigger = useRef<HTMLSpanElement>(null);
  const bubble = useRef<HTMLDivElement>(null);
  const pointer = useRef<{ x: number; y: number } | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const focused = useRef(false);
  const id = useId();
  const transition = useControlTransition(appearance.duration ?? 0.25);
  const clear = () => {
    if (timer.current) clearTimeout(timer.current);
  };
  const schedule = (next: boolean, seconds: number) => {
    clear();
    if (disabled) return;
    timer.current = setTimeout(() => setOpen(next), Math.max(0, seconds) * 1000);
  };
  const place = useCallback(() => {
    const target = trigger.current;
    const tooltip = bubble.current;
    if (!target || !tooltip) return;
    const rect = target.getBoundingClientRect();
    const b = { width: tooltip.offsetWidth, height: tooltip.offsetHeight };
    const point = followPointer && pointer.current && !focused.current ? pointer.current : null;
    const anchor = {
      left: point?.x ?? rect.left,
      right: point?.x ?? rect.right,
      top: point?.y ?? rect.top,
      bottom: point?.y ?? rect.bottom,
    };
    const centerX = (anchor.left + anchor.right) / 2,
      centerY = (anchor.top + anchor.bottom) / 2;
    let side = placement;
    if (side === "top" && anchor.top - b.height - offset < 8) side = "bottom";
    else if (side === "bottom" && anchor.bottom + b.height + offset > innerHeight - 8) side = "top";
    else if (side === "left" && anchor.left - b.width - offset < 8) side = "right";
    else if (side === "right" && anchor.right + b.width + offset > innerWidth - 8) side = "left";
    let x =
      side === "left"
        ? anchor.left - b.width - offset
        : side === "right"
          ? anchor.right + offset
          : centerX - b.width / 2;
    let y =
      side === "top"
        ? anchor.top - b.height - offset
        : side === "bottom"
          ? anchor.bottom + offset
          : centerY - b.height / 2;
    x = Math.max(8, Math.min(x, innerWidth - b.width - 8));
    y = Math.max(8, Math.min(y, innerHeight - b.height - 8));
    setPosition({ x, y, ready: true, side });
  }, [followPointer, placement, offset]);
  useEffect(() => {
    setMounted(true);
    return clear;
  }, []);
  useLayoutEffect(() => {
    if (!isOpen) return;
    place();
    const resize = typeof ResizeObserver !== "undefined" ? new ResizeObserver(place) : null;
    if (bubble.current) resize?.observe(bubble.current);
    window.addEventListener("resize", place);
    window.addEventListener("scroll", place, true);
    return () => {
      resize?.disconnect();
      window.removeEventListener("resize", place);
      window.removeEventListener("scroll", place, true);
    };
  }, [isOpen, place, mounted, content]);
  useEffect(() => {
    if (!isOpen) return;
    const escape = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        clear();
        setOpen(false);
      }
    };
    document.addEventListener("keydown", escape);
    return () => document.removeEventListener("keydown", escape);
  }, [isOpen, setOpen]);
  useEffect(() => {
    if (disabled) {
      clear();
      setOpen(false);
    }
  }, [disabled]);
  return (
    <>
      <ControlStyles />
      <span
        className={`z-mc-tooltip-trigger ${appearance.className ?? ""}`}
        ref={trigger}
        onPointerEnter={(e) => {
          if (e.pointerType === "touch") return;
          pointer.current = { x: e.clientX, y: e.clientY };
          schedule(true, delay);
        }}
        onPointerMove={(e) => {
          pointer.current = { x: e.clientX, y: e.clientY };
          if (isOpen) place();
        }}
        onPointerLeave={() => {
          if (!focused.current) schedule(false, hideDelay);
        }}
        onPointerDown={(e) => {
          if (e.pointerType === "touch") {
            clear();
            setOpen(!isOpen);
          }
        }}
        onFocus={() => {
          focused.current = true;
          pointer.current = null;
          schedule(true, delay);
        }}
        onBlur={() => {
          focused.current = false;
          schedule(false, hideDelay);
        }}
      >
        {cloneElement(children, {
          "aria-describedby":
            [children.props["aria-describedby"], isOpen ? id : undefined]
              .filter(Boolean)
              .join(" ") || undefined,
        })}
      </span>
      {mounted &&
        createPortal(
          <AnimatePresence>
            {isOpen && !disabled && (
              <motion.div
                ref={bubble}
                id={id}
                role="tooltip"
                className="z-mc-tooltip-bubble"
                data-placement={position.side}
                style={{
                  ...controlVariables(appearance),
                  left: position.x,
                  top: position.y,
                  visibility: position.ready ? "visible" : "hidden",
                }}
                initial={{ opacity: 0, scale: 0.92, y: placement === "top" ? 6 : -6 }}
                animate={{ y: 0, opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={transition}
              >
                {content}
              </motion.div>
            )}
          </AnimatePresence>,
          document.body,
        )}
    </>
  );
}
